<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/HgdActorFetcher.php';use Core\CacheStore;use Core\DB;use Core\HgdActorFetcher;$a=array('dry'=>false,'limit'=>0,'sleep'=>2,'quiet'=>false);$argv=isset($argv)?$argv:array();foreach(array_slice($argv,1)as $b){$b=(string)$b;if($b==='--dry'){$a['dry']=true;}elseif($b==='--quiet'){$a['quiet']=true;}elseif(strpos($b,'--limit=')===0){$a['limit']=max(0,(int)substr($b,8));}elseif(strpos($b,'--sleep=')===0){$a['sleep']=max(0,min(30,(int)substr($b,9)));}}try{$c=DB::pdo();$d="SELECT id, source_id, extra FROM media_items"." WHERE source='hongguoduanju' AND type='short'"." AND (extra IS NULL OR extra='' OR extra NOT LIKE '%\"cast\"%' AND extra NOT LIKE '%\"actors\"%')"." ORDER BY id ASC";if($a['limit']>0){$d.=' LIMIT '.(int)$a['limit'];}$e=$c->query($d)->fetchAll();$f=0;foreach($e as $g){$h=json_decode((string)$g['extra'],true);if(!is_array($h)){$h=array();}if(!empty($h['actors'])||!empty($h['cast'])){continue;}$f++;}if($f===0){echo($a['quiet']?"done 0\n":"没有缺演员的短剧条目。\n");exit(0);}if($a['dry']){printf("[dry] 待回填 %d 条（每条间隔 %d 秒，预计 %s）\n",$f,$a['sleep'],gmdate('H:i:s',$f*$a['sleep']));exit(0);}$i=$c->prepare('UPDATE media_items SET extra=?, updated_at=NOW() WHERE id=?');$j=0;$k=0;$l=0;foreach($e as $g){$m=(int)$g['id'];$n=(string)$g['source_id'];$h=json_decode((string)$g['extra'],true);if(!is_array($h)){$h=array();}if(!empty($h['actors'])||!empty($h['cast'])){$l++;continue;}try{$o=HgdActorFetcher::fetch($n);}catch(\Throwable $p){$k++;if(!$a['quiet']){fwrite(STDOUT,"  #$m 抓取异常：".$p->getMessage()."\n");}if($a['sleep']>0){usleep($a['sleep']*1000000);}continue;}if(empty($o)){$l++;if(!$a['quiet']){fwrite(STDOUT,"  #$m 官网无演员数据\n");}if($a['sleep']>0){usleep($a['sleep']*1000000);}continue;}$h['actors']=HgdActorFetcher::formatActors($o,true);$h['cast']=array();foreach($o as $b){$h['cast'][]=array('name'=>$b['name'],'character'=>$b['character'],'profile'=>'');}$i->execute(array(json_encode($h,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$m));$j++;if(!$a['quiet']){fwrite(STDOUT,"  #$m 补采 ".count($o)." 位演员\n");}if($a['sleep']>0){usleep($a['sleep']*1000000);}}if($j>0){CacheStore::invalidateTagCaches();}printf("[done] 回填 %d 条｜跳过 %d 条｜失败 %d 条\n",$j,$l,$k);exit($k>0?1:0);}catch(\Throwable $p){fwrite(STDERR,'回填失败：'.$p->getMessage()."\n");exit(1);}